div.script:
(function () {
    var root = document.getElementById('bc_contact');
    if (!root || root.getAttribute('data-ready')) { return; }
    root.setAttribute('data-ready', '1');
    var q = function (s) { return root.querySelector(s); };
    var form = q('.bc-form'), hitsBox = q('.bc-hits'), state = q('.bc-state'), errBox = q('.bc-error');
    var company = form.elements.company, noReg = form.elements.no_register;
    var base = root.getAttribute('data-base'), token = '', chosen = '', timer = null, serial = 0;

    function msg(code) {
        var el = root.querySelector('[data-msg="' + code + '"]');
        return el ? el.textContent.trim() : code;
    }
    function rpc(url, params) {
        return fetch(base + url, {
            method: 'POST', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: params || {}})
        }).then(function (r) { return r.json(); }).then(function (j) {
            if (j.error) { throw new Error('rpc'); }
            return j.result || {};
        });
    }
    function showError(code) {
        errBox.textContent = code ? msg(code) : '';
        errBox.hidden = !code;
    }
    function loadPuzzle() {
        form.elements.answer.value = '';
        return rpc('/puzzle').then(function (res) {
            token = res.token || '';
            q('.bc-puzzle-q').textContent = res.question || '…';
        }).catch(function () { q('.bc-puzzle-q').textContent = '…'; });
    }
    function clearHits() {
        hitsBox.textContent = '';
        hitsBox.hidden = true;
    }
    function setChosen(hit) {
        chosen = hit ? hit.fnr : '';
        clearHits();
        state.textContent = '';
        if (!hit) { return; }
        var box = document.createElement('div');
        box.className = 'alert alert-success py-2 mb-0';
        var b = document.createElement('strong');
        b.textContent = hit.name;
        box.appendChild(document.createTextNode(msg('chosen') + ' '));
        box.appendChild(b);
        box.appendChild(document.createTextNode(' (' + hit.label + (hit.seat ? ', ' + hit.seat : '') + ') '));
        var change = document.createElement('button');
        change.type = 'button';
        change.className = 'btn btn-link p-0 align-baseline';
        change.textContent = msg('change');
        change.addEventListener('click', function () { setChosen(null); company.focus(); search(); });
        box.appendChild(change);
        state.appendChild(box);
    }
    function showHits(hits) {
        clearHits();
        state.textContent = hits.length ? msg('choose') : msg('no_hits');
        hits.forEach(function (hit) {
            var item = document.createElement('button');
            item.type = 'button';
            item.className = 'list-group-item list-group-item-action bc-hit';
            var name = document.createElement('strong');
            name.textContent = hit.name;
            var small = document.createElement('div');
            small.className = 'small text-muted';
            small.textContent = [hit.label, hit.seat ? msg('seat') + ' ' + hit.seat : '', hit.legal_form].filter(Boolean).join(' · ');
            item.appendChild(name);
            item.appendChild(small);
            item.addEventListener('click', function () { setChosen(hit); });
            hitsBox.appendChild(item);
        });
        hitsBox.hidden = !hits.length;
    }
    function search(retry) {
        var text = company.value.trim(), mine = ++serial;
        if (chosen || noReg.checked || 3 > text.length) { return; }
        state.textContent = msg('searching');
        rpc('/firmensuche', {q: text, token: token}).then(function (res) {
            if (mine !== serial) { return; }
            if (res.error === 'puzzle_expired' && !retry) {
                return loadPuzzle().then(function () { search(true); });
            }
            if (res.error) { state.textContent = ''; showError(res.error); return; }
            showError('');
            showHits(res.hits || []);
        }).catch(function () { if (mine === serial) { state.textContent = ''; showError('register_down'); } });
    }
    company.addEventListener('input', function () {
        if (chosen) { setChosen(null); }
        clearTimeout(timer);
        clearHits();
        state.textContent = '';
        timer = setTimeout(function () { search(); }, 700);
    });
    noReg.addEventListener('change', function () {
        serial++;
        clearTimeout(timer);
        setChosen(null);
        state.textContent = noReg.checked ? msg('not_listed') : '';
        if (!noReg.checked) { search(); }
    });
    q('.bc-new-puzzle').addEventListener('click', loadPuzzle);
    form.addEventListener('submit', function (ev) {
        ev.preventDefault();
        showError('');
        var el = form.elements;
        var emailOk = /^[^@\s]+@[^@\s]+\.[^@\s]{2,}$/.test(el.email.value.trim());
        var code = '';
        if (!el.first_name.value.trim() || !el.last_name.value.trim() || !company.value.trim()) { code = 'missing_name'; }
        else if (!chosen && !noReg.checked) { code = 'no_company_choice'; }
        else if (!emailOk) { code = 'bad_email'; }
        else if (el.message.value.trim().length < 10) { code = 'message_short'; }
        else if (!el.consent.checked) { code = 'no_consent'; }
        else if (!el.answer.value.trim()) { code = 'puzzle_wrong'; }
        if (code) { showError(code); return; }
        var button = q('.bc-send');
        button.disabled = true;
        rpc('/senden', {
            first_name: el.first_name.value, last_name: el.last_name.value, company: company.value,
            fnr: chosen, no_register: noReg.checked, email: el.email.value, phone: el.phone.value,
            message: el.message.value, consent: el.consent.checked, token: token, answer: el.answer.value,
            hp: el.hp.value
        }).then(function (res) {
            if (res.ok) {
                form.hidden = true;
                q('.bc-done').hidden = false;
                q('.bc-done').scrollIntoView({block: 'center'});
                return;
            }
            showError(res.error || 'failed');
            if (res.error === 'puzzle_wrong' || res.error === 'puzzle_expired' || res.error === 'too_fast') { return loadPuzzle(); }
        }).catch(function () { showError('failed'); }).then(function () { button.disabled = false; });
    });
    loadPuzzle();
})();
